/** One vocabulary for the current-status and recorded-event forms.
 * Parse exact activity phrases, never free text containing words like 'drop'.
 * Unknown historical phrases are preserved as details rather than reclassified.
 */
export const DUTY_STATUSES = Object.freeze([
  Object.freeze({id:'OFF',label:'Off Duty'}), Object.freeze({id:'SB',label:'Sleeper Berth'}),
  Object.freeze({id:'D',label:'Driving'}), Object.freeze({id:'ON',label:'On Duty'}),
]);
const BASE = Object.freeze(['Pre-trip inspection','Fuel','Pickup / Loading','Delivery / Unloading','Waiting']);
const TRAILER = Object.freeze(['Drop Load / Trailer','Hook / Pickup Trailer']);
const INTERMODAL = Object.freeze(['Drop Off','Drop & Hook','Hook Empty / Reposition']);
const OTHER = Object.freeze({OFF:Object.freeze(['Off Duty','Break','Parking','Personal Conveyance']),SB:Object.freeze(['Sleeper Berth','Rest']),D:Object.freeze(['Driving','Yard Move'])});
export const ALL_ON_DUTY_ACTIVITIES = Object.freeze([...BASE,...TRAILER,...INTERMODAL]);
const key = value => String(value ?? '').trim().toLowerCase().replace(/\s+/g,' ');
const byKey = new Map(ALL_ON_DUTY_ACTIVITIES.map(value=>[key(value),value]));
byKey.set('pti','Pre-trip inspection'); byKey.set('pretrip','Pre-trip inspection');
byKey.set('pre-trip','Pre-trip inspection'); byKey.set('pre trip inspection','Pre-trip inspection');
export function dutyActivities(status, intermodal=false) {
  return status==='ON' ? [...BASE,...(intermodal?INTERMODAL:TRAILER)] : [...(OTHER[status]||[])];
}
export function parseRecordedActivities(note='', reasons=[]) {
  const selected=[], details=[];
  for(const part of String(note||'').split(/\s*[·•|]\s*/g).map(v=>v.trim()).filter(Boolean)) {
    const known=byKey.get(key(part));
    if(known){if(!selected.includes(known))selected.push(known);}else details.push(part);
  }
  for(const part of Array.isArray(reasons)?reasons:[]) {
    const raw=String(part||'').trim(); if(!raw)continue;
    const known=byKey.get(key(raw))||raw;
    if(!selected.includes(known))selected.push(known);
  }
  return {selected,details};
}
export function composeRecordedActivities(selected=[], details=[]) {
  return [...selected,...details].map(v=>String(v||'').trim()).filter(Boolean).join(' · ');
}
export function activitiesForRecordedEvent(event={},fallbackIntermodal=false) {
  // Past equipment is read from that event; today's trailer never reclassifies it.
  const hasTrailer=[event.hookedTrailer,event.droppedTrailer].some(v=>v && !/^(?:no\s+trailer|none)$/i.test(String(v).trim()));
  const hasIntermodal=[event.hookedContainer,event.droppedContainer,event.hookedChassis,event.droppedChassis].some(Boolean);
  const mode=hasTrailer&&!hasIntermodal?false:hasIntermodal?true:fallbackIntermodal;
  const selected=parseRecordedActivities(event.note,event.reasons).selected;
  return [...new Set([...dutyActivities('ON',mode),...selected])];
}
